using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns viewers of a recent outgoing message in a basic group or a supergroup chat. For video notes and voice notes only users, opened content of the message, are returned. The method can be called if messageProperties.can_get_viewers == true
    /// </summary>
    public Task<TdLib.TdApi.Objects.MessageViewers> GetMessageViewersAsync(long chatId = default, long messageId = default)
    {

           using var activity =  StartCallActivity("GetMessageViewersAsync", typeof(GetMessageViewers).FullName ?? "GetMessageViewersAsync");

           try
           {
             return client.GetMessageViewersAsync(chatId, messageId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
